// All metrics originate from persisted PostgreSQL state, not transient n8n flags.
const r = $input.first().json.report || {};
const m = r.metrics || {}, q = r.quality || {};
const v = (x) => Number.isFinite(Number(x)) ? Number(x) : 0;
const issues=[];
const push=(severity,code,observation,action)=>issues.push({severity,code,observation,action});
const ack=m.acknowledgment||{}, handoff=m.handoff||{}, ai=m.ai_qualification||{};
const ops=m.operations||{}, backlog=ops.backlog_as_of_run||{};
const nurture=(m.nurturing||{}).touches||{};
const n=v((m.intake||{}).leads_received);
const requests=v(ack.requests_queued), accepted=v(ack.provider_accepted);
if(v(backlog.unknown_incidents)>0)push('critical','unknown_outcomes',`${backlog.unknown_incidents} C06 incidents remain unknown; delivery may have happened`,'Inspect provider records and incident state manually; do NOT resend blindly');
if(v(backlog.overdue_handoffs)>0)push('critical','overdue_handoffs',`${backlog.overdue_handoffs} handoffs are overdue as of this report`,'Inspect Canvas 04 assignments and SLA transitions; verify active reps and manager escalation');
if(v(backlog.dead_outbox)>0)push('high','dead_dispatch',`${backlog.dead_outbox} durable dispatch jobs are dead`,'Triage outbox errors and known vs unknown provider outcomes before any replay');
if(requests>0 && accepted<requests)push('high','ack_coverage',`${accepted}/${requests} queued acknowledgment requests have provider acceptance as of this report`,'Check consent, quiet hours, recipient allowlist, disabled SMS, pending jobs, and provider status');
if(ack.acceptance_p95_minutes !== null && ack.acceptance_p95_minutes !== undefined && v(ack.acceptance_p95_minutes)>10)
 push('medium','ack_latency',`P95 provider-acceptance time ${ack.acceptance_p95_minutes} minutes (heuristic threshold: 10m)`,'Review queue age, quiet-hours deferrals and capacity; this is not an agreed contractual SLA');
if(v(nurture.unknown)>0)push('high','nurture_unknown',`${nurture.unknown} nurture touches in the intake cohort have unknown delivery outcome`,'Reconcile provider outcomes manually before resending');
const states=(m.crm||{}).current_provider_contact_states||[];
const bad=states.filter(x=>['blocked','unknown'].includes(String(x.state)));
const badN=bad.reduce((s,x)=>s+v(x.count),0);
if(badN>0)push('high','crm_attention',`${badN} provider-contact sync state(s) blocked or unknown (systemwide snapshot)`,'Review Canvas 05 auth, ownership, provider contact IDs and mismatch evidence');
if(v(ai.jobs)>0 && v(ai.done)<v(ai.jobs))
 push('medium','qualification_pending',`${v(ai.done)}/${v(ai.jobs)} qualification jobs completed for intake cohort`,'Review fallback, model errors and queued qualification; do not block intake or acknowledgment');
if(n===0)push('info','no_cohort_data','No leads for the selected Karachi local-day intake cohort','Use Manual Trigger on a date with fixtures, or wait for recorded events');
if(issues.length===0)push('info','no_detected_bottleneck','No configured operational exception thresholds were crossed','Continue monitoring; this is not proof of zero customer issues');
const severityOrder={critical:0,high:1,medium:2,info:3};
issues.sort((a,b)=>(severityOrder[a.severity]??9)-(severityOrder[b.severity]??9));
const lines=[`ENGINE1 DAILY OPERATIONS REPORT | ${r.report_day} | Asia/Karachi`,
 `Lead intake cohort: ${n}; converted as of run: ${v((m.intake||{}).converted_cohort_as_of_run)}`,
 `Acknowledgment: queued ${requests}, accepted ${accepted}, delivered ${v(ack.delivered)}; accepted P50/P95 minutes ${ack.acceptance_p50_minutes??'N/A'}/${ack.acceptance_p95_minutes??'N/A'}`,
 `Handoff: ${v(handoff.handoffs)} records, ${v(handoff.claimed)} claimed; assignment-to-claim P95 ${handoff.assignment_to_claim_p95_minutes??'N/A'} min`,
 `Qualification: ${v(ai.done)}/${v(ai.jobs)} done; average score ${ai.avg_score??'N/A'}; accuracy UNAVAILABLE (no truth labels)`,
 `Nurture: ${v(nurture.delivered)} confirmed delivered, ${v(nurture.unknown)} unknown touches`,
 `Operational: ${v(backlog.open_incidents)} pending C06 incidents, ${v(backlog.unknown_incidents)} unknown, ${v(backlog.dead_outbox)} dead dispatch jobs`,
 ...issues.map((x,i)=>`${i+1}. [${x.severity.toUpperCase()}] ${x.code}: ${x.observation}. Action: ${x.action}`),
 `QUALITY: ${q.response_measure||''}. Causal uplift, AI accuracy and AI cost are unavailable without verified additional data.`
];
return [{json:{report_day:r.report_day,metrics:m,quality:q,insights:issues,report_text:lines.join('\n'),generated_at:r.generated_at}}];

const latest=$('R2 · Bottlenecks & Optimization (No AI Guessing)').first().json;
const persisted=$('R3 · Persist Insights (Daily Upsert)').first().json.saved||{};
const rows=$input.all().map(i=>i.json).filter(x=>x&&x.report_day);
const s=rows.map(x=>({day:x.report_day,leads:Number(x.metrics?.intake?.leads_received||0),accepted:Number(x.metrics?.acknowledgment?.provider_accepted||0),delivered:Number(x.metrics?.acknowledgment?.delivered||0),converted_cohort_as_of_snapshot:Number(x.metrics?.intake?.converted_cohort_as_of_run||0)}));
const last7=s.slice(0,7);
const t={days_available:s.length,last7_leads:last7.reduce((v,x)=>v+x.leads,0),last7_provider_accepted:last7.reduce((v,x)=>v+x.accepted,0),last7_delivered:last7.reduce((v,x)=>v+x.delivered,0)};
// Conversion is cohort-as-of-snapshot: NEVER add across days and call it a daily conversion event count.
const text=latest.report_text+'\n\nTREND (stored reports, latest 7 days): '+t.days_available+' total days available, '+t.last7_leads+' leads, '+t.last7_provider_accepted+' provider accepted acknowledgments, '+t.last7_delivered+' confirmed delivered.\nSnapshot saved: '+persisted.action+'.';
return [{json:{action:persisted.action==='saved'?'report_ready':'persistence_needs_attention',report_day:latest.report_day,summary:text,insights:latest.insights,quality:latest.quality,metrics:latest.metrics,trend:t,daily_points:s,persisted}}];

parameters.query:
SELECT table_name, count(*)::integer AS columns_count FROM information_schema.columns
WHERE table_schema='public' AND (table_name IN ('leads','event_log','crm_sync_legs','engine1_dispatch_outbox') OR table_name LIKE 'engine1_c0%')
GROUP BY table_name ORDER BY table_name;
